#include <queue>
#include <vector>
#include <stdexcept>
#include <utility>

int kthLargest(const std::vector<int>& a, int k) {
    if (k <= 0 || k > static_cast<int>(a.size()))
        throw std::invalid_argument("k out of range");
    // 小根堆：greater<int> 让最小值在堆顶
    // 用区间构造一次建堆（自底向上），复杂度 O(k)
    std::vector<int> first(a.begin(), a.begin() + k);
    std::priority_queue<int, std::vector<int>, std::greater<int>>
        heap(std::greater<int>(), std::move(first));
    for (int i = k; i < static_cast<int>(a.size()); ++i) {
        if (a[i] > heap.top()) {                  // 只有大于堆顶才可能进前 k
            heap.pop();
            heap.push(a[i]);
        }
    }
    return heap.top();
}
```

