#include <queue>
#include <vector>

class MedianFinder {
    std::priority_queue<int> low;                                  // 大根堆
    std::priority_queue<int, std::vector<int>, std::greater<int>> high; // 小根堆
public:
    void addNum(int num) {
        if (low.empty() || num <= low.top()) low.push(num);
        else high.push(num);
        if (low.size() > high.size() + 1) { high.push(low.top()); low.pop(); }
        else if (high.size() > low.size()) { low.push(high.top()); high.pop(); }
    }
    double findMedian() const {
        if (low.size() == high.size())
            return (static_cast<double>(low.top()) + high.top()) / 2.0;
        return low.top();
    }
};
